import React, { lazy, Suspense, useLayoutEffect, useRef } from 'react';
import { ArrowDown, Infinity as InfinityIcon } from 'lucide-react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { GithubIcon } from '../common/Icons';
import { RoomBoundary, RoomFallback } from './RoomFallback';

const Room = lazy(() => import('./CinematicRoom'));
gsap.registerPlugin(ScrollTrigger);
export type SceneProgress = { value: number; invalidate?: () => void };

export const Hero: React.FC = () => {
  const root = useRef<HTMLDivElement>(null);
  const progress = useRef<SceneProgress>({ value: 0 });
  useLayoutEffect(() => {
    const media = gsap.matchMedia();
    media.add('(prefers-reduced-motion: no-preference)', () => {
      const ctx = gsap.context(() => {
        gsap.to(progress.current, {
          value: 1, ease: 'none',
          onUpdate: () => {
            progress.current.invalidate?.();
            root.current?.style.setProperty('--sequence', String(progress.current.value));
          },
          scrollTrigger: { trigger: root.current, pin: root.current?.querySelector('.hero-viewport'), pinSpacing: false, anticipatePin: 1, start: 'top top', end: 'bottom bottom', scrub: 0.65, invalidateOnRefresh: true },
        });
      }, root);
      return () => ctx.revert();
    });
    return () => media.revert();
  }, []);
  return (
    <div id="hero" ref={root} className="cinematic-hero">
      <div className="hero-viewport">
        <div className="hero-room" aria-hidden="true"><RoomBoundary><Suspense fallback={<RoomFallback />}><Room progress={progress.current} /></Suspense></RoomBoundary></div>
        <div className="hero-room-shade" aria-hidden="true" />
        <div className="hero-halo" aria-hidden="true" />
        <div className="hero-copy-wrap"><div id="hero-text-col" className="hero-copy">
          <div className="hero-eyebrow"><span />Full-Stack Developer</div>
          <h1><span>Abdullah</span><span>Azaam</span></h1>
          <p>Building scalable web applications<br className="hidden sm:block" /> and immersive digital experiences.</p>
          <div className="hero-actions">
            <a href="#projects" className="hero-primary">View My Work <ArrowDown size={16} /></a>
            <a href="https://github.com/abdullahazaam" target="_blank" rel="noopener noreferrer" className="hero-secondary"><GithubIcon size={16} />GitHub</a>
          </div>
          <div className="hero-stats">
            <div><strong>5+</strong><span>Major Projects</span></div>
            <div><strong>15+</strong><span>Technologies</span></div>
            <div><strong><InfinityIcon size={28} /></strong><span>Always Learning</span></div>
          </div>
        </div></div>
        <a href="#about" className="hero-scroll"><span className="scroll-track"><i /></span><span>SCROLL DOWN</span></a>
        <div className="hero-progress" aria-hidden="true"><i /></div>
      </div>
    </div>
  );
};

