﻿import React, { useState, useRef, useEffect } from "react";
import { motion } from "framer-motion";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { DotNetIcon, CSharpIcon, DatabaseIcon, LaravelIcon, ReactIcon, ThreeJsIcon } from "../common/Icons";

gsap.registerPlugin(ScrollTrigger);

export const DeveloperCoreVisual: React.FC = () => {
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);
  const innerRef = useRef<HTMLDivElement>(null);
  const coreRef = useRef<HTMLDivElement>(null);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width - 0.5;
    const y = (e.clientY - rect.top) / rect.height - 0.5;
    setMousePos({ x, y });
  };

  const handleMouseLeave = () => setMousePos({ x: 0, y: 0 });

  // 3D scroll-driven perspective reveal
  useEffect(() => {
    if (!containerRef.current || !innerRef.current) return;
    const ctx = gsap.context(() => {
      gsap.fromTo(
        innerRef.current,
        { rotateY: -18, rotateX: 8, scale: 0.9, opacity: 0.6 },
        {
          rotateY: 0,
          rotateX: 0,
          scale: 1,
          opacity: 1,
          duration: 1.2,
          ease: "power3.out",
          scrollTrigger: {
            trigger: containerRef.current,
            start: "top 80%",
            toggleActions: "play none none reverse",
          },
        }
      );
    }, containerRef);
    return () => ctx.revert();
  }, []);

  // Core pulse
  useEffect(() => {
    if (!coreRef.current) return;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const tween = gsap.to(coreRef.current, {
      boxShadow: "0 0 55px rgba(229,9,20,0.75), 0 0 20px rgba(229,9,20,0.5)",
      scale: 1.06,
      duration: 2,
      repeat: -1,
      yoyo: true,
      ease: "sine.inOut",
    });
    return () => { tween.kill(); };
  }, []);

  const nodes = [
    { name: ".NET", label: "Framework", angle: -90, icon: <DotNetIcon size={20} className="text-[#E50914]" /> },
    { name: "React", label: "Frontend", angle: -30, icon: <ReactIcon size={20} className="text-[#E50914]" /> },
    { name: "Three.js", label: "3D WebGL", angle: 30, icon: <ThreeJsIcon size={20} className="text-[#E50914]" /> },
    { name: "SQL Server", label: "Database", angle: 90, icon: <DatabaseIcon size={20} className="text-[#E50914]" /> },
    { name: "Laravel", label: "Backend", angle: 150, icon: <LaravelIcon size={20} className="text-[#E50914]" /> },
    { name: "C#", label: "Language", angle: 210, icon: <CSharpIcon size={20} className="text-[#E50914]" /> },
  ];

  const radius = 128;

  return (
    <div
      ref={containerRef}
      className="relative w-full max-w-[400px] aspect-square"
      style={{ perspective: "1200px" }}
    >
      <div
        ref={innerRef}
        onMouseMove={handleMouseMove}
        onMouseLeave={handleMouseLeave}
        className="premium-card relative w-full h-full rounded-3xl bg-[#080808]/90 border border-neutral-900/90 flex items-center justify-center overflow-hidden shadow-[0_25px_60px_rgba(0,0,0,0.9)] group hover:border-red-950/70 transition-colors will-change-transform"
        style={{
          transformStyle: "preserve-3d",
          transform: `rotateY(${mousePos.x * 12}deg) rotateX(${mousePos.y * -10}deg)`,
          transition: "transform 0.35s cubic-bezier(0.2,0.8,0.2,1)",
        }}
      >
        {/* Deep red radial glow inside */}
        <div
          className="absolute w-72 h-72 rounded-full blur-3xl pointer-events-none"
          style={{
            background: "radial-gradient(circle, rgba(120,0,0,0.45) 0%, rgba(229,9,20,0.18) 50%, transparent 80%)",
            transform: `translate(${mousePos.x * 28}px, ${mousePos.y * 28}px)`,
            transition: "transform 0.4s ease-out",
          }}
        />

        {/* Outer orbit rings */}
        <div className="absolute w-[270px] h-[270px] rounded-full border border-red-900/30 pointer-events-none" />
        <div className="absolute w-[315px] h-[315px] rounded-full border border-neutral-800/50 border-dashed animate-spin [animation-duration:110s] pointer-events-none" />

        {/* Connecting beams SVG */}
        <svg className="absolute inset-0 w-full h-full pointer-events-none" viewBox="0 0 400 400">
          <defs>
            <linearGradient id="beamGrad" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="#E50914" stopOpacity="0.8" />
              <stop offset="100%" stopColor="#780000" stopOpacity="0.15" />
            </linearGradient>
            <filter id="glow">
              <feGaussianBlur stdDeviation="1.5" result="coloredBlur" />
              <feMerge><feMergeNode in="coloredBlur" /><feMergeNode in="SourceGraphic" /></feMerge>
            </filter>
          </defs>
          {nodes.map((node, i) => {
            const rad = (node.angle * Math.PI) / 180;
            const tx = 200 + radius * Math.cos(rad);
            const ty = 200 + radius * Math.sin(rad);
            return (
              <line
                key={i}
                x1="200" y1="200"
                x2={tx} y2={ty}
                stroke="url(#beamGrad)"
                strokeWidth="1.2"
                strokeDasharray="4 4"
                filter="url(#glow)"
                opacity="0.65"
              />
            );
          })}
        </svg>

        {/* Central AA Core */}
        <motion.div
          ref={coreRef}
          animate={{ scale: [1, 1.05, 1] }}
          transition={{ duration: 3.5, repeat: Infinity, ease: "easeInOut" }}
          className="relative z-10 w-24 h-24 rounded-full bg-gradient-to-br from-[#200000] via-[#3A0000] to-[rgba(229,9,20,0.35)] border-2 border-[#E50914] flex flex-col items-center justify-center"
          style={{
            boxShadow: "0 0 35px rgba(229,9,20,0.55)",
            transform: `translate(${mousePos.x * 14}px, ${mousePos.y * 14}px)`,
            transition: "transform 0.4s ease-out",
          }}
        >
          <span className="font-display font-extrabold text-2xl tracking-wider text-white drop-shadow-[0_0_10px_rgba(255,255,255,0.6)]">
            AA
          </span>
          <div className="absolute -top-1 -right-1 w-3 h-3 rounded-full bg-[#E50914] shadow-[0_0_10px_#E50914] animate-ping" />
        </motion.div>

        {/* 6 Orbiting Tech Nodes */}
        {nodes.map((node, index) => {
          const rad = (node.angle * Math.PI) / 180;
          const x = radius * Math.cos(rad);
          const y = radius * Math.sin(rad);
          return (
            <motion.div
              key={node.name}
              initial={{ opacity: 0, scale: 0.5 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: 0.15 + index * 0.1 }}

              style={{
                position: "absolute",
                left: `calc(50% + ${x}px - 30px)`,
                top: `calc(50% + ${y}px - 30px)`,
                transform: `translate(${mousePos.x * 18}px, ${mousePos.y * 18}px)`,
                transition: "transform 0.4s ease-out",
              }}
              className="premium-card z-20 w-[60px] h-[60px] rounded-2xl bg-[#0C0C0C]/95 border border-neutral-800/90 flex flex-col items-center justify-center hover:border-red-600 hover:shadow-[0_0_18px_rgba(229,9,20,0.45)] hover:scale-110 transition-all cursor-default"
            >
              {node.icon}
              <span className="font-sans font-semibold text-[9px] text-neutral-300 mt-1 truncate max-w-[52px] text-center">
                {node.name}
              </span>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
};

