export const ProjectCard: React.FC<ProjectCardProps> = ({ project, index, prominent = false }) => {
  // Requirement 8: Scroll reveal variations
  // NEXUS: reveals from slight left/depth
  // Hamara Commerce: reveals from slight right/depth
  // Lower projects: stagger upward one after another
  const getInitialMotion = () => {
    if (index === 0) return { opacity: 0, x: -35, rotateY: 5, rotateX: 2 };
    if (index === 1) return { opacity: 0, x: 35, rotateY: -5, rotateX: 2 };
    return { opacity: 0, y: 35, rotateX: 6, rotateY: 0 };
  };

  return (
    <motion.div
      initial={getInitialMotion()}
      whileInView={{ opacity: 1, x: 0, y: 0, rotateX: 0, rotateY: 0 }}
      viewport={{ once: true, margin: '-60px' }}
      transition={{ duration: 0.65, delay: index * 0.08, ease: 'easeOut' }}
      className={`premium-card project-card ${prominent ? "featured-card" : ""} group relative rounded-2xl bg-[#0A0A0A]/95 border transition-colors duration-300 flex flex-col justify-between overflow-hidden ${
