        {/* Tech Stack Pills right below Title matching full-structure.png */}
        <div className="flex flex-wrap gap-1.5 mt-2.5">
          {project.tags.map((tag) => (
            <span
              key={tag}
              className="px-2.5 py-0.5 rounded bg-[#121212] border border-neutral-800/80 font-sans text-[11px] text-neutral-300 font-medium"
            >
              {tag}
            </span>
          ))}
        </div>

        {/* Short Description */}
        <p className="mt-3 font-sans text-xs sm:text-sm text-neutral-300 leading-relaxed line-clamp-3">
          {project.shortDescription}
        </p>
      </div>

      {/* Footer: Action Buttons matching full-structure.png */}
      <div className="mt-6 pt-4 border-t border-neutral-900/90 flex items-center gap-2.5">
        {project.liveUrl ? (
          <a
            href={project.liveUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="flex-1 inline-flex items-center justify-center gap-1.5 px-4 py-2.5 rounded-xl bg-[#E50914] text-white font-sans font-semibold text-xs uppercase tracking-wider shadow-[0_0_15px_rgba(229,9,20,0.35)] hover:shadow-[0_0_25px_rgba(229,9,20,0.6)] hover:bg-[#ff1e2b] transition-all active:scale-[0.98]"
          >
            <span>Live Demo</span>
            <ArrowRight className="w-3.5 h-3.5" />
          </a>
        ) : (
          <a
            href={project.githubUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="flex-1 inline-flex items-center justify-center gap-1.5 px-4 py-2.5 rounded-xl bg-[#E50914] text-white font-sans font-semibold text-xs uppercase tracking-wider shadow-[0_0_15px_rgba(229,9,20,0.35)] hover:shadow-[0_0_25px_rgba(229,9,20,0.6)] hover:bg-[#ff1e2b] transition-all active:scale-[0.98]"
